INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒヨリ", "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 0, 8, 44, "人助け、応援", 27, "人助けが大好き！　前向き格闘娘", "トゥインクルウィッシュ", 100101, 155, 2, 16, "獣人族", "東山奈央");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユイ", "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, 4, 47, "料理、人間観察", 5, "戦闘のサポートが得意な、心優しい少女", "トゥインクルウィッシュ", 100201, 158, 2, 17, "ヒューマン", "種田梨沙");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("レイ", "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 0, 1, 46, "読書、乗馬、お茶", 12, "クールで何事にも真っ直ぐな剣士", "トゥインクルウィッシュ", 100301, 163, 2, 18, "魔族", "早見沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミソギ", "O", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 0, 8, 27, "いたずら、探検", 10, "探検好きのイタズラっ子", "リトルリリカル", 100401, 128, 5, 9, "ヒューマン", "諸星すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("マツリ", "O", "？？？", 0, 11, 40, "ヒーローごっこ", 25, "ヒーローに憧れる騎士見習いの少女", "王宮騎士団（NIGHTMARE）", 100501, 146, 8, 12, "獣人族", "下田麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アカリ", "O", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 0, 11, 42, "サックス", 22, "甘え上手なみんなの人気者", "悪魔偽王国軍（ディアボロス）", 100601, 150, 7, 13, "魔族", "浅倉杏美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミヤコ", "B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 0, 1, 32, "プリンを食べること", 23, "プリン大好きゴースト娘", "悪魔偽王国軍（ディアボロス）", 100701, 130, 7, 14, "魔族", "雨宮天");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユキ", "AB", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 0, 10, 40, "鏡で自分を見ること", 10, "ボクは誰よりも美しい", "ヴァイスフリューゲル　ランドソル支部", 100801, 150, 15, 14, "エルフ", "大空直美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アンナ", "A", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 0, 7, 45, "小説執筆", 5, "前世を信じる中二病患者、「疾風の冥姫」", "トワイライトキャラバン", 100901, 159, 13, 17, "魔族", "髙野麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("マホ", "O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 0, 9, 42, "空想、ぬいぐるみ集め", 22, "マホマホ王国のプリンセス", "自警団（カォン）", 101001, 155, 10, 16, "獣人族", "内田真礼");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("リノ", "A", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 0, 8, 44, "お裁縫", 25, "人懐っこくてマシンガントークな妹系少女", "ラビリンス", 101101, 156, 3, 15, "ヒューマン", "阿澄佳奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ハツネ", "A", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 0, 12, 46, "妹と遊ぶこと、二度寝、昼寝、早寝", 24, "みんなのために超能力を使う眠り姫", "フォレスティエ", 101201, 156, 6, 17, "エルフ", "大橋彩香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ナナカ", "O", "", 0, 8, 55, "読書、魔法", 21, "オタク全開な魔法少女", "トワイライトキャラバン", 101301, 166, 13, 18, "魔族", "佳村はるか");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("カスミ", "AB", "test", 0, 11, 41, "読書、推理", 3, "頭脳明晰な美少女名探偵", "自警団（カォン）", 101401, 152, 10, 15, "獣人族", "水瀬いのり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミサト", "O", "test", 0, 9, 54, "絵本作り", 5, "母性溢れる優しいみんなの「ミサト先生」", "フォレスティエ", 101501, 165, 6, 21, "エルフ", "國府田マリ子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("スズナ", "O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 0, 4, 48, "ファッション", 10, "天真爛漫で人気者のカリスマモデル", "ルーセント学院", 101601, 167, 14, 17, "魔族", "上坂すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("カオリ", "A", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 0, 7, 53, "踊り、空手", 7, "いつでも「なんくるないさ～」な天然娘", "自警団（カォン）", 101701, 158, 10, 17, "獣人族", "高森奈津美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("イオ", "B", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 0, 8, 52, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 14, "多くの男性を魅了する無垢な女教師", "ルーセント学院", 101801, 162, 14, 23, "魔族", "伊藤静");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミミ", "O", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 0, 4, 21, "かわいいもの集め", 3, "お歌もにんじんも、ウサギさんも大好き♪", "リトルリリカル", 102001, 117, 5, 10, "獣人族", "日高里菜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クルミ", "B", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 0, 6, 40, "観劇、おままごと", 9, "泣き虫で臆病な守ってあげたい女の子", "サレンディア救護院", 102101, 150, 9, 12, "ヒューマン", "植田佳奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヨリ", "O", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 0, 11, 40, "ゲーム全般", 22, "人見知りであまのじゃくな女の子", "悪魔偽王国軍（ディアボロス）", 102201, 150, 7, 13, "魔族", "原紗友里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アヤネ", "B", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 0, 5, 38, "屋内でできる遊び", 10, "ぷうきちといつも一緒！", "サレンディア救護院", 102301, 148, 9, 14, "ヒューマン", "芹澤優");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("スズメ", "O", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 0, 12, 43, "ご奉仕", 12, "お嬢さまのためにがんばるドジっ娘メイド", "サレンディア救護院", 102501, 154, 9, 15, "ヒューマン", "悠木碧");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("リン", "B", "test", 0, 1, 42, "あんパン", 1, "遊びと睡眠が何より大事なぐうたら娘", "牧場（エリザベスパーク）", 102601, 144, 11, 17, "獣人族", "小岩井ことり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エリコ", "B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 0, 7, 43, "実験、裁縫、料理", 30, "運命の相手に一途すぎる乙女", "トワイライトキャラバン", 102701, 154, 13, 16, "魔族", "橋本ちなみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("サレン", "A", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 0, 10, 43, "経営、お茶会", 4, "救護院を経営する優しい庶民派お嬢様", "サレンディア救護院", 102801, 156, 9, 17, "エルフ", "堀江由衣");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ノゾミ", "B", "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", 0, 1, 40, "舞台鑑賞、ダンス", 24, "歌って踊れる大人気アイドル", "カルミナ", 102901, 157, 4, 17, "ヒューマン", "日笠陽子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ニノン", "O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 0, 8, 51, "忍法開発", 31, "トーゴクの神秘、オシエテクダサイ！", "ヴァイスフリューゲル　ランドソル支部", 103001, 163, 15, 16, "ヒューマン", "佐藤聡美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("シノブ", "AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 0, 12, 42, "占い", 22, "占いが得意な霊能少女", "悪魔偽王国軍（ディアボロス）", 103101, 157, 7, 18, "魔族", "大坪由佳");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アキノ", "AB", "この私とともにいる限り、\nお金に不自由はさせませんわ！", 0, 3, 45, "慈善事業", 12, "一人前の商人を目指すパワフルお嬢様", "メルクリウス財団", 103201, 157, 12, 18, "ヒューマン", "松嵜麗");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("マヒル", "B", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 0, 3, 35, "漫才", 3, "みんなを笑顔にするお笑い牧場主", "牧場（エリザベスパーク）", 103301, 142, 11, 20, "ヒューマン", "新田恵海");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユカリ", "A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 0, 3, 55, "ウインドーショッピング", 16, "純情でほっとけない大人の女性", "メルクリウス財団", 103401, 164, 12, 22, "エルフ", "今井麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("キョウカ", "A", "test", 0, 2, 21, "お勉強", 2, "礼儀正しくしっかり者のちびっ子優等生", "リトルリリカル", 103601, 118, 5, 8, "エルフ", "小倉唯");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("トモ", "A", "test", 0, 8, 43, "剣術、年長者をからかう", 11, "義理堅くてからかい好きな剣術少女", "王宮騎士団（NIGHTMARE）", 103701, 149, 8, 13, "ヒューマン", "茅原実里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("シオリ", "A", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 0, 11, 40, "読書、お散歩", 3, "読書が趣味の病弱少女", "牧場（エリザベスパーク）", 103801, 153, 11, 14, "獣人族", "小清水亜美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アオイ", "AB", "友達ができるその日まで…\nBB団で\nトレーニングですっ！", 0, 6, 44, "友達作りのイメトレ", 6, "「友達」に憧れる、エルフの森の女の子", "フォレスティエ", 104001, 158, 6, 13, "エルフ", "花澤香菜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("チカ", "O", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 0, 6, 46, "各種楽器", 3, "人々を守るために歌う、唱喚士の少女", "カルミナ", 104201, 163, 4, 17, "ヒューマン", "福原綾香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("マコト", "O", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 0, 8, 54, "お菓子作り", 9, "男勝りで情に厚いワイルド娘", "自警団（カォン）", 104301, 168, 10, 17, "獣人族", "小松未可子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("イリヤ", "A", "test", 0, 5, 50, "世界征服", 5, "かつては夜を支配した最強の吸血鬼", "悪魔偽王国軍（ディアボロス）", 104401, 172, 7, "??", "魔族", "丹下桜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クウカ", "AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 0, 11, 49, "小説を読むこと", 19, "妄想大好き！　ほんとは照れ屋な女の子", "ヴァイスフリューゲル　ランドソル支部", 104501, 157, 15, 18, "ヒューマン", "長妻樹里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("タマキ", "AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 0, 3, 48, "猫とたわむれること", 1, "弱きを助け強きをくじく猫娘", "メルクリウス財団", 104601, 158, 12, 19, "獣人族", "沼倉愛美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ジュン", "A", "？？？", 0, 10, 50, "格闘技、湯浴み", 25, "素顔を見せない冷静沈着な女性騎士", "王宮騎士団（NIGHTMARE）", 104701, 171, 8, 25, "ヒューマン", "川澄綾子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミフユ", "O", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 0, 11, 49, "傭兵などのアルバイト", 11, "仕事も私事も効率優先な傭兵少女", "メルクリウス財団", 104801, 163, 12, 20, "ヒューマン", "田所あずさ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("シズル", "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 0, 10, 54, "家事全般", 24, "お姉ちゃんがお世話してあげるからねっ！", "ラビリンス", 104901, 168, 3, 18, "ヒューマン", "生天目仁美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミサキ", "A", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 0, 1, 22, "ファッション誌鑑賞、コスメ集め", 3, "ちょっとおませな恋に恋する女の子", "ルーセント学院", 105001, 120, 14, 11, "魔族", "久野美咲");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミツキ", "A", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 0, 3, 53, "研究、実験", 7, "実験が趣味の危険な科学者", "トワイライトキャラバン", 105101, 166, 13, 27, "ヒューマン", "三石琴乃");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("リマ", "A", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", 0, 3, 100, "毛繕い、お喋り", 14, "乙女チックなもふもふアニマル", "牧場（エリザベスパーク）", 105201, 150, 11, 17, "獣人族", "徳井青空");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("モニカ", "A", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 0, 7, 33, "お菓子屋通い", 28, "見た目も中身もお子ちゃまな異国の軍人", "ヴァイスフリューゲル　ランドソル支部", 105301, 140, 15, 17, "ヒューマン", "辻あゆみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ツムギ", "AB", "test", 0, 9, 45, "裁縫", 7, "ファッション大好きなキュートガール", "カルミナ", 105401, 153, 4, 14, "ヒューマン", "木戸衣吹");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アユミ", "O", "test", 0, 4, 43, "観察", 7, "どこまでも一途に慕う、純情乙女", "ヴァイスフリューゲル　ランドソル支部", 105501, 155, 15, 16, "エルフ", "大関英里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ルカ", "B", "test", 0, 7, 54, "釣り", 11, "人情味溢れる粋でいなせな「姉御」", "トワイライトキャラバン", 105601, 167, 13, 25, "ヒューマン", "佐藤利奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ジータ", "O", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", 0, 3, 45, "冒険、おしゃべり", 10, "空への冒険を夢見る騎空士の少女", "？？？", 105701, 156, "", 17, "ヒューマン", "金元寿子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ペコリーヌ", "O", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 0, 3, 46, "食べ歩き、料理", 31, "いつも元気な腹ペコ少女", "美食殿", 105801, 156, 1, 17, "ヒューマン", "M・A・O");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("コッコロ", "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 0, 5, 35, "瞑想、動植物の飼育", 11, "主を慕う、小さなガイド役", "美食殿", 105901, 140, 1, 11, "エルフ", "伊藤美来");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("キャル", "A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 0, 9, 39, "猫と遊ぶ", 2, "行き倒れの謎のネコミミ魔法使い", "美食殿", 106001, 152, 1, 14, "獣人族", "立花理香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ムイミ", "O", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", 0, 8, 40, "冒険、思い出話", 11, "さまよえる謎の少女", "？？？", 106101, 148, "", 16, "ヒューマン", "潘めぐみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アリサ", "O", "", 0, 6, 42, "キレイな葉っぱを集めること", 17, "森番を目指すエルフの少女", "？？？", 106301, 155, "", 15, "エルフ", "優木かな");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("シェフィ", "B", "", 0, 12, "???", "読書、ストレッチ", 14, "記憶喪失のドラゴン娘", "美食殿", 106401, 147, 1, 14, "ドラゴン族", "近藤玲奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("カヤ", "B", "", 0, 6, "???", "格闘技", 25, "拳で語る喧嘩屋ドラゴン少女", "ドラゴンズネスト", 106501, 156, 17, 16, "ドラゴン族", "小市眞琴");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("イノリ", "AB", "", 0, 9, "???", "ゲーム", 29, "口が達者なヘタレドラゴン", "ドラゴンズネスト", 106601, 145, 17, 13, "ドラゴン族", "藤田茜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ホマレ", "O", "", 0, 4, "???", "絵画、読書", 17, "妖しい微笑で全てを見透かす臥竜の頭領", "ドラゴンズネスト", 106701, 168, 17, 25, "ドラゴン族", "大西沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ラビリスタ", "AB", "", 0, 7, "??", "人間観察", 25, "秘密結社ラビリンスの『迷宮女王』", "ラビリンス", 106801, 160, 3, 25, "ヒューマン", "沢城みゆき");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("カイザーインサイト", "AB", "", 0, 7, "??", "占い、支配", 1, "謎に包まれたランドソルの主", "？？？", 106901, 166, "", 29, "獣人族", "蒼井翔太");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ネネカ", "O", "", 0, 3, "??", "物真似、芸術鑑賞", 24, "研究所に隠れ住む物静かなお姉さん", "？？？", 107001, 149, "", 24, "エルフ", "井口裕香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クリスティーナ", "O", "", 0, 2, "??", "強敵との闘争", 7, "傍若無人な王宮騎士団副団長", "王宮騎士団（NIGHTMARE）", 107101, 165, 8, 27, "ヒューマン", "たかはし智秋");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ペコリーヌ（サマー）", "O", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 0, 3, 46, "食べ歩き、料理", 31, "いつも元気な腹ペコ少女", "美食殿", 107501, 156, 1, 17, "ヒューマン", "M・A・O");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("コッコロ（サマー）", "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 0, 5, 35, "瞑想、動植物の飼育", 11, "主を慕う、小さなガイド役", "美食殿", 107601, 140, 1, 11, "エルフ", "伊藤美来");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("スズメ（サマー）", "O", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 0, 12, 43, "ご奉仕", 12, "お嬢さまのためにがんばるドジっ娘メイド", "サレンディア救護院", 107701, 154, 9, 15, "ヒューマン", "悠木碧");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("キャル（サマー）", "A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 0, 9, 39, "猫と遊ぶ", 2, "行き倒れの謎のネコミミ魔法使い", "美食殿", 107801, 152, 1, 14, "獣人族", "立花理香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("タマキ（サマー）", "AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 0, 3, 48, "猫とたわむれること", 1, "弱きを助け強きをくじく猫娘", "メルクリウス財団", 107901, 158, 12, 19, "獣人族", "沼倉愛美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミフユ（サマー）", "O", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 0, 11, 49, "傭兵などのアルバイト", 11, "仕事も私事も効率優先な傭兵少女", "メルクリウス財団", 108001, 163, 12, 20, "ヒューマン", "田所あずさ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("シノブ（ハロウィン）", "AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 0, 12, 42, "占い", 22, "占いが得意な霊能少女", "悪魔偽王国軍（ディアボロス）", 108101, 157, 7, 18, "魔族", "大坪由佳");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミヤコ（ハロウィン）", "B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 0, 1, 32, "プリンを食べること", 23, "プリン大好きゴースト娘", "悪魔偽王国軍（ディアボロス）", 108201, 130, 7, 14, "魔族", "雨宮天");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミサキ（ハロウィン）", "A", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 0, 1, 22, "ファッション誌鑑賞、コスメ集め", 3, "ちょっとおませな恋に恋する女の子", "ルーセント学院", 108301, 120, 14, 11, "魔族", "久野美咲");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("チカ（クリスマス）", "O", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 0, 6, 46, "各種楽器", 3, "人々を守るために歌う、唱喚士の少女", "カルミナ", 108401, 163, 4, 17, "ヒューマン", "福原綾香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クルミ（クリスマス）", "B", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 0, 6, 40, "観劇、おままごと", 9, "泣き虫で臆病な守ってあげたい女の子", "サレンディア救護院", 108501, 150, 9, 12, "ヒューマン", "植田佳奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アヤネ（クリスマス）", "B", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 0, 5, 38, "屋内でできる遊び", 10, "ぷうきちといつも一緒！", "サレンディア救護院", 108601, 148, 9, 14, "ヒューマン", "芹澤優");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒヨリ（ニューイヤー）", "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 0, 8, 44, "人助け、応援", 27, "人助けが大好き！　前向き格闘娘", "トゥインクルウィッシュ", 108701, 155, 2, 16, "獣人族", "東山奈央");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユイ（ニューイヤー）", "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, 4, 47, "料理、人間観察", 5, "戦闘のサポートが得意な、心優しい少女", "トゥインクルウィッシュ", 108801, 158, 2, 17, "ヒューマン", "種田梨沙");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("レイ（ニューイヤー）", "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 0, 1, 46, "読書、乗馬、お茶", 12, "クールで何事にも真っ直ぐな剣士", "トゥインクルウィッシュ", 108901, 163, 2, 18, "魔族", "早見沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エリコ（バレンタイン）", "B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 0, 7, 43, "実験、裁縫、料理", 30, "運命の相手に一途すぎる乙女", "トワイライトキャラバン", 109001, 154, 13, 16, "魔族", "橋本ちなみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("シズル（バレンタイン）", "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 0, 10, 54, "家事全般", 24, "お姉ちゃんがお世話してあげるからねっ！", "ラビリンス", 109101, 168, 3, 18, "ヒューマン", "生天目仁美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アン", "AB", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", 0, 12, 55, "読書", 1, "英霊と契約を結んだマナリアの天才王女", "？？？", 109201, 156, "", 17, "ヒューマン", "日笠陽子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ルゥ", "O", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", 0, 2, 45, "食べること、眠ること", 4, "マナリア魔法学院の新入生", "？？？", 109301, 144, "", 16, "ヒューマン", "こやまきみこ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("グレア", "B", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", 0, 11, 67, "ピアノ", 3, "人を超越した力を有す心優しい竜姫", "？？？", 109401, 167, "", 17, "半人半竜", "福原綾香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クウカ（オーエド）", "AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 0, 11, 49, "小説を読むこと", 19, "妄想大好き！　ほんとは照れ屋な女の子", "ヴァイスフリューゲル　ランドソル支部", 109501, 157, 15, 18, "ヒューマン", "長妻樹里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ニノン（オーエド）", "O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 0, 8, 51, "忍法開発", 31, "トーゴクの神秘、オシエテクダサイ！", "ヴァイスフリューゲル　ランドソル支部", 109601, 163, 15, 16, "ヒューマン", "佐藤聡美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("レム", "?", "", 0, 2, "??", "演劇鑑賞、詩文", 2, "鬼がかりの万能妹メイド", "？？？", 109701, 154, "", 17, "鬼族", "水瀬いのり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ラム", "?", "", 0, 2, "??", "読書", 2, "毒舌系鬼姉メイド", "？？？", 109801, 154, "", 17, "鬼族", "村川梨衣");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エミリア", "?", "", 0, 9, "??", "パックの毛繕い、勉強", 23, "銀髪のおっとりハーフエルフ", "？？？", 109901, 164, "", "??", "ハーフエルフ", "高橋李依");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("スズナ（サマー）", "O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 0, 4, 48, "ファッション", 10, "天真爛漫で人気者のカリスマモデル", "ルーセント学院", 110001, 167, 14, 17, "魔族", "上坂すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("イオ（サマー）", "B", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 0, 8, 52, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 14, "多くの男性を魅了する無垢な女教師", "ルーセント学院", 110101, 162, 14, 23, "魔族", "伊藤静");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミサキ（サマー）", "A", "", 0, 1, 22, "ファッション誌鑑賞、コスメ集め", 3, "ちょっとおませな恋に恋する女の子", "ルーセント学院", 110201, 120, 14, 11, "魔族", "久野美咲");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("サレン（サマー）", "A", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 0, 10, 43, "経営、お茶会", 4, "救護院を経営する優しい庶民派お嬢様", "サレンディア救護院", 110301, 156, 9, 17, "エルフ", "堀江由衣");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("マコト（サマー）", "O", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 0, 8, 54, "お菓子作り", 9, "男勝りで情に厚いワイルド娘", "自警団（カォン）", 110401, 168, 10, 17, "獣人族", "小松未可子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("カオリ（サマー）", "A", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 0, 7, 53, "踊り、空手", 7, "いつでも「なんくるないさ～」な天然娘", "自警団（カォン）", 110501, 158, 10, 17, "獣人族", "高森奈津美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("マホ（サマー）", "O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 0, 9, 42, "空想、ぬいぐるみ集め", 22, "マホマホ王国のプリンセス", "自警団（カォン）", 110601, 155, 10, 16, "獣人族", "内田真礼");
