INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クロエ", "O", "", 0, 8, 42, "ダーツ", 7, "ダウンタウン育ちのダウナー系エルフ", "聖テレサ女学院（なかよし部）", 110801, 154, 16, 17, "エルフ", "種﨑敦美");
