INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("キョウカ（ハロウィン）", "A", "", 0, 2, 21, "お勉強", 2, "礼儀正しくしっかり者のちびっ子優等生", "リトルリリカル", 111101, 118, 5, 8, "エルフ", "小倉唯");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミソギ（ハロウィン）", "O", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 0, 8, 27, "いたずら、探検", 10, "探検好きのイタズラっ子", "リトルリリカル", 111201, 128, 5, 9, "ヒューマン", "諸星すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミミ（ハロウィン）", "O", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 0, 4, 21, "かわいいもの集め", 3, "お歌もにんじんも、ウサギさんも大好き♪", "リトルリリカル", 111301, 117, 5, 10, "獣人族", "日高里菜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ルナ", "?", "", 0, 1, 28, "「おともだち」を探すこと", 8, "おともだちを探す死霊術師の少女", "？？？", 111401, 142, "", "??", "ヒューマン", "小倉唯");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クリスティーナ（クリスマス）", "O", "", 0, 2, "??", "強敵との闘争", 7, "傍若無人な王宮騎士団副団長", "王宮騎士団（NIGHTMARE）", 111501, 165, 8, 27, "ヒューマン", "たかはし智秋");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ノゾミ（クリスマス）", "B", "", 0, 1, 40, "舞台鑑賞、ダンス", 24, "歌って踊れる大人気アイドル", "カルミナ", 111601, 157, 4, 17, "ヒューマン", "日笠陽子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("イリヤ（クリスマス）", "A", "", 0, 5, 50, "世界征服", 5, "かつては夜を支配した最強の吸血鬼", "悪魔偽王国軍（ディアボロス）", 111701, 172, 7, "??", "魔族", "丹下桜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ぺコリーヌ（ニューイヤー）", "O", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 0, 3, 46, "食べ歩き、料理", 31, "いつも元気な腹ペコ少女", "美食殿", 111801, 156, 1, 17, "ヒューマン", "M・A・O");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("コッコロ（ニューイヤー）", "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 0, 5, 35, "瞑想、動植物の飼育", 11, "主を慕う、小さなガイド役", "美食殿", 111901, 140, 1, 11, "エルフ", "伊藤美来");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("キャル（ニューイヤー）", "A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 0, 9, 39, "猫と遊ぶ", 2, "行き倒れの謎のネコミミ魔法使い", "美食殿", 112001, 152, 1, 14, "獣人族", "立花理香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("スズメ（ニューイヤー）", "O", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 0, 12, 43, "ご奉仕", 12, "お嬢さまのためにがんばるドジっ娘メイド", "サレンディア救護院", 112101, 154, 9, 15, "ヒューマン", "悠木碧");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("カスミ（マジカル）", "AB", "", 0, 11, 41, "読書、推理", 3, "頭脳明晰な美少女名探偵", "自警団（カォン）", 112201, 152, 10, 15, "獣人族", "水瀬いのり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("シオリ（マジカル）", "A", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 0, 11, 40, "読書、お散歩", 3, "読書が趣味の病弱少女", "牧場（エリザベスパーク）", 112301, 153, 11, 14, "獣人族", "小清水亜美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ウヅキ（デレマス）", "O", "", 0, 4, 45, "友達と長話", 24, "弾ける笑顔！　アイドルを夢見る女の子", "ニュージェネレーションズ", 112401, 159, 100, 17, "ヒューマン", "大橋彩香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("リン（デレマス）", "B", "", 0, 8, 44, "犬の散歩", 10, "クールビューティーな「蒼の剣士」", "ニュージェネレーションズ", 112501, 165, 100, 15, "ヒューマン", "福原綾香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミオ（デレマス）", "B", "", 0, 12, 46, "ショッピング", 1, "スーパースターを目指す元気娘☆☆★", "ニュージェネレーションズ", 112601, 161, 100, 15, "ヒューマン", "原紗友里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("リン（レンジャー）", "B", "", 0, 1, 42, "あんパン", 1, "遊びと睡眠が何より大事なぐうたら娘", "牧場（エリザベスパーク）", 112701, 144, 11, 17, "獣人族", "小岩井ことり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("マヒル（レンジャー）", "B", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 0, 3, 35, "漫才", 3, "みんなを笑顔にするお笑い牧場主", "牧場（エリザベスパーク）", 112801, 142, 11, 20, "ヒューマン", "新田恵海");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("リノ（ワンダー）", "A", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 0, 8, 44, "お裁縫", 25, "人懐っこくてマシンガントークな妹系少女", "ラビリンス", 112901, 156, 3, 15, "ヒューマン", "阿澄佳奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アユミ（ワンダー）", "O", "", 0, 4, 43, "観察", 7, "どこまでも一途に慕う、純情乙女", "ヴァイスフリューゲル　ランドソル支部", 113001, 155, 15, 16, "エルフ", "大関英里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ルカ（サマー）", "B", "", 0, 7, 54, "釣り", 11, "人情味溢れる粋でいなせな「姉御」", "トワイライトキャラバン", 113101, 167, 13, 25, "ヒューマン", "佐藤利奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アンナ（サマー）", "A", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 0, 7, 45, "小説執筆", 5, "前世を信じる中二病患者、「疾風の冥姫」", "トワイライトキャラバン", 113201, 159, 13, 17, "魔族", "髙野麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ナナカ（サマー）", "O", "", 0, 8, 55, "読書、魔法", 21, "オタク全開な魔法少女", "トワイライトキャラバン", 113301, 166, 13, 18, "魔族", "佳村はるか");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ハツネ（サマー）", "A", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 0, 12, 46, "妹と遊ぶこと、二度寝、昼寝、早寝", 24, "みんなのために超能力を使う眠り姫", "フォレスティエ", 113401, 156, 6, 17, "エルフ", "大橋彩香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミサト（サマー）", "O", "", 0, 9, 54, "絵本作り", 5, "母性溢れる優しいみんなの「ミサト先生」", "フォレスティエ", 113501, 165, 6, 21, "エルフ", "國府田マリ子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ジュン（サマー）", "A", "", 0, 10, 50, "格闘技、湯浴み", 25, "素顔を見せない冷静沈着な女性騎士", "王宮騎士団（NIGHTMARE）", 113601, 171, 8, 25, "ヒューマン", "川澄綾子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アカリ（エンジェル）", "O", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 0, 11, 42, "サックス", 22, "甘え上手なみんなの人気者", "悪魔偽王国軍（ディアボロス）", 113701, 150, 7, 13, "魔族", "浅倉杏美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヨリ（エンジェル）", "O", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 0, 11, 40, "ゲーム全般", 22, "人見知りであまのじゃくな女の子", "悪魔偽王国軍（ディアボロス）", 113801, 150, 7, 13, "魔族", "原紗友里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ツムギ（ハロウィン）", "AB", "", 0, 9, 45, "裁縫", 7, "ファッション大好きなキュートガール", "カルミナ", 113901, 153, 4, 14, "ヒューマン", "木戸衣吹");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("レイ（ハロウィン）", "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 0, 1, 46, "読書、乗馬、お茶", 12, "クールで何事にも真っ直ぐな剣士", "トゥインクルウィッシュ", 114001, 163, 2, 18, "魔族", "早見沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("マツリ（ハロウィン）", "O", "", 0, 11, 40, "ヒーローごっこ", 25, "ヒーローに憧れる騎士見習いの少女", "王宮騎士団（NIGHTMARE）", 114101, 146, 8, 12, "獣人族", "下田麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("モニカ（マジカル）", "A", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 0, 7, 33, "お菓子屋通い", 28, "見た目も中身もお子ちゃまな異国の軍人", "ヴァイスフリューゲル　ランドソル支部", 114201, 140, 15, 17, "ヒューマン", "辻あゆみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("トモ（マジカル）", "A", "", 0, 8, 43, "剣術、年長者をからかう", 11, "義理堅くてからかい好きな剣術少女", "王宮騎士団（NIGHTMARE）", 114301, 149, 8, 13, "ヒューマン", "茅原実里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アキノ（クリスマス）", "AB", "この私とともにいる限り、\nお金に不自由はさせませんわ！", 0, 3, 45, "慈善事業", 12, "一人前の商人を目指すパワフルお嬢様", "メルクリウス財団", 114401, 157, 12, 18, "ヒューマン", "松嵜麗");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("サレン（クリスマス）", "A", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 0, 10, 43, "経営、お茶会", 4, "救護院を経営する優しい庶民派お嬢様", "サレンディア救護院", 114501, 156, 9, 17, "エルフ", "堀江由衣");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユカリ（クリスマス）", "A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 0, 3, 55, "ウインドーショッピング", 16, "純情でほっとけない大人の女性", "メルクリウス財団", 114601, 164, 12, 22, "エルフ", "今井麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ムイミ（ニューイヤー）", "O", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", 0, 8, 40, "冒険、思い出話", 11, "さまよえる謎の少女", "？？？", 114701, 148, "", 16, "ヒューマン", "潘めぐみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ネネカ（ニューイヤー）", "O", "", 0, 3, "??", "物真似、芸術鑑賞", 24, "研究所に隠れ住む物静かなお姉さん", "？？？", 115001, 149, "", 24, "エルフ", "井口裕香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("コッコロ（儀装束）", "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 0, 5, 35, "瞑想、動植物の飼育", 11, "主を慕う、小さなガイド役", "美食殿", 115501, 140, 1, 11, "エルフ", "伊藤美来");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユイ（儀装束）", "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, 4, 47, "料理、人間観察", 5, "戦闘のサポートが得意な、心優しい少女", "トゥインクルウィッシュ", 115601, 158, 2, 17, "ヒューマン", "種田梨沙");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("カスミ（サマー）", "AB", "", 0, 11, 41, "読書、推理", 3, "頭脳明晰な美少女名探偵", "自警団（カォン）", 115701, 152, 10, 15, "獣人族", "水瀬いのり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("リマ（シンデレラ）", "A", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", 0, 3, 100, "毛繕い、お喋り", 14, "乙女チックなもふもふアニマル", "牧場（エリザベスパーク）", 115801, 150, 11, 17, "獣人族", "徳井青空");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("マコト（シンデレラ）", "O", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 0, 8, 54, "お菓子作り", 9, "男勝りで情に厚いワイルド娘", "自警団（カォン）", 115901, 168, 10, 17, "獣人族", "小松未可子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("マホ（シンデレラ）", "O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 0, 9, 42, "空想、ぬいぐるみ集め", 22, "マホマホ王国のプリンセス", "自警団（カォン）", 116001, 155, 10, 16, "獣人族", "内田真礼");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クロエ（聖学祭）", "O", "", 0, 8, 42, "ダーツ", 7, "ダウンタウン育ちのダウナー系エルフ", "聖テレサ女学院（なかよし部）", 116201, 154, 16, 17, "エルフ", "種﨑敦美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("チエル（聖学祭）", "O", "", 0, 9, 46, "ダンス、カラオケ", 15, "自由奔放ナチュラル無礼な現代っ子", "聖テレサ女学院（なかよし部）", 116301, 156, 16, 16, "ヒューマン", "佐倉綾音");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユニ（聖学祭）", "O", "", 0, 2, 36, "読書", 28, "書庫に眠れる小さな賢人", "聖テレサ女学院（なかよし部）", 116401, 142, 16, 18, "ヒューマン", "小原好美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("イノリ（タイムトラベル）", "AB", "", 0, 9, "???", "ゲーム", 29, "口が達者なヘタレドラゴン", "ドラゴンズネスト", 116501, 145, 17, 13, "ドラゴン族", "藤田茜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("カヤ（タイムトラベル）", "B", "", 0, 6, "???", "格闘技", 25, "拳で語る喧嘩屋ドラゴン少女", "ドラゴンズネスト", 116601, 156, 17, 16, "ドラゴン族", "小市眞琴");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アオイ（作業服）", "AB", "", 0, 6, 44, "友達作りのイメトレ", 6, "「友達」に憧れる、エルフの森の女の子", "フォレスティエ", 116701, 158, 6, 13, "エルフ", "花澤香菜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("タマキ（作業服）", "AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 0, 3, 48, "猫とたわむれること", 1, "弱きを助け強きをくじく猫娘", "メルクリウス財団", 116801, 158, 12, 19, "獣人族", "沼倉愛美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミフユ（作業服）", "O", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 0, 11, 49, "傭兵などのアルバイト", 11, "仕事も私事も効率優先な傭兵少女", "メルクリウス財団", 116901, 163, 12, 20, "ヒューマン", "田所あずさ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エリコ（サマー）", "B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 0, 7, 43, "実験、裁縫、料理", 30, "運命の相手に一途すぎる乙女", "トワイライトキャラバン", 117001, 154, 13, 16, "魔族", "橋本ちなみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("シズル（サマー）", "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 0, 10, 54, "家事全般", 24, "お姉ちゃんがお世話してあげるからねっ！", "ラビリンス", 117101, 168, 3, 18, "ヒューマン", "生天目仁美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ノゾミ（サマー）", "B", "", 0, 1, 40, "舞台鑑賞、ダンス", 24, "歌って踊れる大人気アイドル", "カルミナ", 117201, 157, 4, 17, "ヒューマン", "日笠陽子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("チカ（サマー）", "O", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 0, 6, 46, "各種楽器", 3, "人々を守るために歌う、唱喚士の少女", "カルミナ", 117301, 163, 4, 17, "ヒューマン", "福原綾香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ツムギ（サマー）", "AB", "", 0, 9, 45, "裁縫", 7, "ファッション大好きなキュートガール", "カルミナ", 117401, 153, 4, 14, "ヒューマン", "木戸衣吹");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミツキ（オーエド）", "A", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 0, 3, 53, "研究、実験", 7, "実験が趣味の危険な科学者", "トワイライトキャラバン", 117501, 166, 13, 27, "ヒューマン", "三石琴乃");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユキ（オーエド）", "AB", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 0, 10, 40, "鏡で自分を見ること", 10, "ボクは誰よりも美しい", "ヴァイスフリューゲル　ランドソル支部", 117601, 150, 15, 14, "エルフ", "大空直美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("カオリ（ハロウィン）", "A", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 0, 7, 53, "踊り、空手", 7, "いつでも「なんくるないさ～」な天然娘", "自警団（カォン）", 117701, 158, 10, 17, "獣人族", "高森奈津美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ニノン（ハロウィン）", "O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 0, 8, 51, "忍法開発", 31, "トーゴクの神秘、オシエテクダサイ！", "ヴァイスフリューゲル　ランドソル支部", 117801, 163, 15, 16, "ヒューマン", "佐藤聡美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("スズナ（ハロウィン）", "O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 0, 4, 48, "ファッション", 10, "天真爛漫で人気者のカリスマモデル", "ルーセント学院", 117901, 167, 14, 17, "魔族", "上坂すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クレジッタ", "A", "", 0, 9, 57, "お金を数えること、悪だくみ", 19, "忠義に目覚めた女商人", "リッチモンド商工会", 118001, 160, 18, 26, "ヒューマン", "Lynn");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ランファ", "O", "", 0, 12, 53, "歌、読書、詩を書くこと", 28, "静寂を求め歌う陰気少女", "レイジ・レギオン", 118101, 165, 19, 20, "魔族", "原田彩楓");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミソラ", "A", "", 0, 7, "??", "特に無し", 2, "明朗快活、なれど破滅に流るる溌溂少女", "レイジ・レギオン", 118201, 159, 19, 16, "ヒューマン", "鬼頭明里");
