INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ネビア", "?", "", 0, "?", "???", "悪戯をすること", "?", "幻霧に戯れる悪戯好きなガイド妖精", "？？？", 118601, "???", "", "??", "？？？", "相坂優歌");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("イオ（ノワール）", "B", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 0, 8, 52, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 14, "多くの男性を魅了する無垢な女教師", "ルーセント学院", 119001, 162, 14, 23, "魔族", "伊藤静");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クウカ（ノワール）", "AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 0, 11, 49, "小説を読むこと", 19, "妄想大好き！　ほんとは照れ屋な女の子", "ヴァイスフリューゲル　ランドソル支部", 119101, 157, 15, 18, "ヒューマン", "長妻樹里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("マヒル（クリスマス）", "B", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 0, 3, 35, "漫才", 3, "みんなを笑顔にするお笑い牧場主", "牧場（エリザベスパーク）", 119201, 142, 11, 20, "ヒューマン", "新田恵海");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("リノ（クリスマス）", "A", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 0, 8, 44, "お裁縫", 25, "人懐っこくてマシンガントークな妹系少女", "ラビリンス", 119301, 156, 3, 15, "ヒューマン", "阿澄佳奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミヤコ（クリスマス）", "B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 0, 1, 32, "プリンを食べること", 23, "プリン大好きゴースト娘", "悪魔偽王国軍（ディアボロス）", 119901, 130, 7, 14, "魔族", "雨宮天");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("シズル（ノワール）", "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 0, 10, 54, "家事全般", 24, "お姉ちゃんがお世話してあげるからねっ！", "ラビリンス", 120001, 168, 3, 18, "ヒューマン", "生天目仁美");
