INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("イリヤ（ニューイヤー）", "A", "", 0, 5, 50, "世界征服", 5, "かつては夜を支配した最強の吸血鬼", "悪魔偽王国軍（ディアボロス）", 120901, 172, 7, "??", "魔族", "丹下桜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ぺコリーヌ（オーバーロード）", "O", "", 0, 3, 46, "食べ歩き、料理", 31, "いつも元気な腹ペコ少女", "美食殿", 121001, 156, 1, 17, "ヒューマン", "M・A・O");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("キャル（オーバーロード）", "A", "", 0, 9, 39, "猫と遊ぶ", 2, "行き倒れの謎のネコミミ魔法使い", "美食殿", 121101, 152, 1, 14, "獣人族", "立花理香");
