INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クルミ（ステージ）", "B", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 0, 6, 40, "観劇、おままごと", 9, "泣き虫で臆病な守ってあげたい女の子", "サレンディア救護院", 121301, 150, 9, 12, "ヒューマン", "植田佳奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミサキ（ステージ）", "A", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 0, 1, 22, "ファッション誌鑑賞、コスメ集め", 3, "ちょっとおませな恋に恋する女の子", "ルーセント学院", 121401, 120, 14, 11, "魔族", "久野美咲");
