INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アンナ（パイレーツ）", "A", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 0, 7, 45, "小説執筆", 5, "前世を信じる中二病患者、「疾風の冥姫」", "トワイライトキャラバン", 121901, 159, 13, 17, "魔族", "髙野麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("シノブ（パイレーツ）", "AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 0, 12, 42, "占い", 22, "占いが得意な霊能少女", "悪魔偽王国軍（ディアボロス）", 122001, 157, 7, 18, "魔族", "大坪由佳");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アオイ（キャンプ）", "AB", "", 0, 6, 44, "友達作りのイメトレ", 6, "「友達」に憧れる、エルフの森の女の子", "フォレスティエ", 122101, 158, 6, 13, "エルフ", "花澤香菜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユカリ（キャンプ）", "A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 0, 3, 55, "ウインドーショッピング", 16, "純情でほっとけない大人の女性", "メルクリウス財団", 122201, 164, 12, 22, "エルフ", "今井麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヴァンピィ", "AB", "", 0, 12, 41, "お散歩、お料理", 6, "けんぞくのご主人様", "？？？", 122301, 149, "", "??", "魔族", "釘宮理恵");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒヨリ（サマー）", "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 0, 8, 44, "人助け、応援", 27, "人助けが大好き！　前向き格闘娘", "トゥインクルウィッシュ", 122401, 155, 2, 16, "獣人族", "東山奈央");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("レイ（サマー）", "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 0, 1, 46, "読書、乗馬、お茶", 12, "クールで何事にも真っ直ぐな剣士", "トゥインクルウィッシュ", 122501, 163, 2, 18, "魔族", "早見沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユイ（サマー）", "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, 4, 47, "料理、人間観察", 5, "戦闘のサポートが得意な、心優しい少女", "トゥインクルウィッシュ", 122601, 158, 2, 17, "ヒューマン", "種田梨沙");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("キョウカ（サマー）", "A", "", 0, 2, 21, "お勉強", 2, "礼儀正しくしっかり者のちびっ子優等生", "リトルリリカル", 122701, 118, 5, 8, "エルフ", "小倉唯");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミソギ（サマー）", "O", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 0, 8, 27, "いたずら、探検", 10, "探検好きのイタズラっ子", "リトルリリカル", 122801, 128, 5, 9, "ヒューマン", "諸星すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミミ（サマー）", "O", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 0, 4, 21, "かわいいもの集め", 3, "お歌もにんじんも、ウサギさんも大好き♪", "リトルリリカル", 122901, 117, 5, 10, "獣人族", "日高里菜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アメス", "?", "", 0, "?", "???", "？？？", "?", "新たな姿で騎士の冒険を支え続ける妖精", "？？？", 123001, 150, "", "??", "？？？", "相坂優歌");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("マホ（エクスプローラー）", "O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 0, 9, 42, "空想、ぬいぐるみ集め", 22, "マホマホ王国のプリンセス", "自警団（カォン）", 123101, 155, 10, 16, "獣人族", "内田真礼");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アヤネ（エクスプローラー）", "B", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 0, 5, 38, "屋内でできる遊び", 10, "ぷうきちといつも一緒！", "サレンディア救護院", 123201, 148, 9, 14, "ヒューマン", "芹澤優");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ネア", "B", "", 0, 6, 55, "可愛いショタと遊ぶ、買い物", 13, "ショタ大好き♪　ギャル系スライム娘", "レイジ・レギオン", 123301, 157, 19, 19, "魔族？", "和氣あず未");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ジュン（キャンプ）", "A", "", 0, 10, 50, "格闘技、湯浴み", 25, "素顔を見せない冷静沈着な女性騎士", "王宮騎士団（NIGHTMARE）", 123401, 171, 8, 25, "ヒューマン", "川澄綾子");
