INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クリスティーナ（ワイルド）", "O", "", 0, 2, "??", "強敵との闘争", 7, "傍若無人な王宮騎士団副団長", "王宮騎士団（NIGHTMARE）", 123801, 165, 8, 27, "ヒューマン", "たかはし智秋");
