INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アカリ（クリスマス）", "O", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 0, 11, 42, "サックス", 22, "甘え上手なみんなの人気者", "悪魔偽王国軍（ディアボロス）", 124001, 150, 7, 13, "魔族", "浅倉杏美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヨリ（クリスマス）", "O", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 0, 11, 40, "ゲーム全般", 22, "人見知りであまのじゃくな女の子", "悪魔偽王国軍（ディアボロス）", 124101, 150, 7, 13, "魔族", "原紗友里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ジュン（クリスマス）", "A", "", 0, 10, 50, "格闘技、湯浴み", 25, "素顔を見せない冷静沈着な女性騎士", "王宮騎士団（NIGHTMARE）", 124201, 171, 8, 25, "ヒューマン", "川澄綾子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ホマレ（ニューイヤー）", "O", "", 0, 4, "???", "絵画、読書", 17, "妖しい微笑で全てを見透かす臥竜の頭領", "ドラゴンズネスト", 124501, 168, 17, 25, "ドラゴン族", "大西沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミサト（ニューイヤー）", "O", "", 0, 9, 54, "絵本作り", 5, "母性溢れる優しいみんなの「ミサト先生」", "フォレスティエ", 124601, 165, 6, 21, "エルフ", "國府田マリ子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ミツキ（ニューイヤー）", "A", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 0, 3, 53, "研究、実験", 7, "実験が趣味の危険な科学者", "トワイライトキャラバン", 124701, 166, 13, 27, "ヒューマン", "三石琴乃");
