INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("カヤ（リベレイター）", "B", "", 0, 6, "???", "格闘技", 25, "拳で語る喧嘩屋ドラゴン少女", "ドラゴンズネスト", 124901, 156, 17, 16, "ドラゴン族", "小市眞琴");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ムイミ（リベレイター）", "O", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", 0, 8, 40, "冒険、思い出話", 11, "さまよえる謎の少女", "？？？", 125001, 148, "", 16, "ヒューマン", "潘めぐみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("タマキ（カフェ）", "AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 0, 3, 48, "猫とたわむれること", 1, "弱きを助け強きをくじく猫娘", "メルクリウス財団", 125101, 158, 12, 19, "獣人族", "沼倉愛美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("モニカ（カフェ）", "A", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 0, 7, 33, "お菓子屋通い", 28, "見た目も中身もお子ちゃまな異国の軍人", "ヴァイスフリューゲル　ランドソル支部", 125201, 140, 15, 17, "ヒューマン", "辻あゆみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("コッコロ（レンジャー）", "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 0, 5, 35, "瞑想、動植物の飼育", 11, "主を慕う、小さなガイド役", "美食殿", 125301, 140, 1, 11, "エルフ", "伊藤美来");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("シオリ（レンジャー）", "A", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 0, 11, 40, "読書、お散歩", 3, "読書が趣味の病弱少女", "牧場（エリザベスパーク）", 125401, 153, 11, 14, "獣人族", "小清水亜美");
