INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユキ（儀装束）", "AB", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 0, 10, 40, "鏡で自分を見ること", 10, "ボクは誰よりも美しい", "ヴァイスフリューゲル　ランドソル支部", 126301, 150, 15, 14, "エルフ", "大空直美");
