INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("アキノ（サマー）", "AB", "この私とともにいる限り、\nお金に不自由はさせませんわ！", 0, 3, 45, "慈善事業", 12, "一人前の商人を目指すパワフルお嬢様", "メルクリウス財団", 126701, 157, 12, 18, "ヒューマン", "松嵜麗");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユカリ（サマー）", "A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 0, 3, 55, "ウインドーショッピング", 16, "純情でほっとけない大人の女性", "メルクリウス財団", 126801, 164, 12, 22, "エルフ", "今井麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ランファ（サマー）", "O", "", 0, 12, 53, "歌、読書、詩を書くこと", 28, "静寂を求め歌う陰気少女", "レイジ・レギオン", 126901, 165, 19, 20, "魔族", "原田彩楓");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クウカ（サマー）", "AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 0, 11, 49, "小説を読むこと", 19, "妄想大好き！　ほんとは照れ屋な女の子", "ヴァイスフリューゲル　ランドソル支部", 127001, 157, 15, 18, "ヒューマン", "長妻樹里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("シノブ（サマー）", "AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 0, 12, 42, "占い", 22, "占いが得意な霊能少女", "悪魔偽王国軍（ディアボロス）", 127101, 157, 7, 18, "魔族", "大坪由佳");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("キャル（編入生）", "A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 0, 9, 39, "猫と遊ぶ", 2, "行き倒れの謎のネコミミ魔法使い", "美食殿", 127201, 152, 1, 14, "獣人族", "立花理香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("スズナ（編入生）", "O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 0, 4, 48, "ファッション", 10, "天真爛漫で人気者のカリスマモデル", "ルーセント学院", 127301, 167, 14, 17, "魔族", "上坂すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("サレン（サラサリア）", "A", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 0, 10, 43, "経営、お茶会", 4, "救護院を経営する優しい庶民派お嬢様", "サレンディア救護院", 127501, 156, 9, 17, "エルフ", "堀江由衣");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ルカ（サラサリア）", "B", "", 0, 7, 54, "釣り", 11, "人情味溢れる粋でいなせな「姉御」", "トワイライトキャラバン", 127601, 167, 13, 25, "ヒューマン", "佐藤利奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("リンド", "?", "", 0, 2, "???", "妹と過ごす休日", 5, "真面目で一生懸命なドラゴンメイド（姉）", "？？？", 127701, 145, "", 12, "ドラゴン族", "豊田萌絵");
