INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ペコリーヌ（クリスマス）", "O", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 0, 3, 46, "食べ歩き、料理", 31, "いつも元気な腹ペコ少女", "美食殿", 127901, 156, 1, 17, "ヒューマン", "M・A・O");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("クレジッタ（クリスマス）", "A", "", 0, 9, 57, "お金を数えること、悪だくみ", 19, "忠義に目覚めた女商人", "リッチモンド商工会", 128001, 160, 18, 26, "ヒューマン", "Lynn");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("イノリ（ニューイヤー）", "AB", "", 0, 9, "???", "ゲーム", 29, "口が達者なヘタレドラゴン", "ドラゴンズネスト", 128301, 145, 17, 13, "ドラゴン族", "藤田茜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ハツネ（ニューイヤー）", "A", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 0, 12, 46, "妹と遊ぶこと、二度寝、昼寝、早寝", 24, "みんなのために超能力を使う眠り姫", "フォレスティエ", 128401, 156, 6, 17, "エルフ", "大橋彩香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("カスミ（ニューイヤー）", "AB", "", 0, 11, 41, "読書、推理", 3, "頭脳明晰な美少女名探偵", "自警団（カォン）", 128501, 152, 10, 15, "獣人族", "水瀬いのり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒヨリ（アストラル）", "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 0, 8, 44, "人助け、応援", 27, "人助けが大好き！　前向き格闘娘", "トゥインクルウィッシュ", 128701, 155, 2, 16, "獣人族", "東山奈央");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("レイ（アストラル）", "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 0, 1, 46, "読書、乗馬、お茶", 12, "クールで何事にも真っ直ぐな剣士", "トゥインクルウィッシュ", 128801, 163, 2, 18, "魔族", "早見沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユイ（アストラル）", "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, 4, 47, "料理、人間観察", 5, "戦闘のサポートが得意な、心優しい少女", "トゥインクルウィッシュ", 128901, 158, 2, 17, "ヒューマン", "種田梨沙");
