INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エリコ（コマンダー）", "B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 0, 7, 43, "実験、裁縫、料理", 30, "運命の相手に一途すぎる乙女", "トワイライトキャラバン", 129901, 154, 13, 16, "魔族", "橋本ちなみ");
