INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("スズメ（スプリング）", "O", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 0, 12, 43, "ご奉仕", 12, "お嬢さまのためにがんばるドジっ娘メイド", "サレンディア救護院", 130801, 154, 9, 15, "ヒューマン", "悠木碧");
