INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("マホ（ドリームパーク）", "O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 0, 9, 42, "空想、ぬいぐるみ集め", 22, "マホマホ王国のプリンセス", "自警団（カォン）", 131001, 155, 10, 16, "獣人族", "内田真礼");
