INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("イオ（クリスマス）", "B", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 0, 8, 52, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 14, "多くの男性を魅了する無垢な女教師", "ルーセント学院", 132901, 162, 14, 23, "魔族", "伊藤静");
