INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ユイ（クリスマス）", "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, 4, 47, "料理、人間観察", 5, "戦闘のサポートが得意な、心優しい少女", "トゥインクルウィッシュ", 136401, 158, 2, 17, "ヒューマン", "種田梨沙");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("シズル（ニューイヤー）", "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 0, 10, 54, "家事全般", 24, "お姉ちゃんがお世話してあげるからねっ！", "ラビリンス", 136501, 168, 3, 18, "ヒューマン", "生天目仁美");
