INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒヨリ（プリンセス）", "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 0, 8, 44, "人助け、応援", 27, "人助けが大好き！　前向き格闘娘", "トゥインクルウィッシュ", 180101, 155, 2, 16, "獣人族", "東山奈央");
