INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("キャル（プリンセス）", "A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 0, 9, 39, "猫と遊ぶ", 2, "行き倒れの謎のネコミミ魔法使い", "美食殿", 180601, 152, 1, 14, "獣人族", "立花理香");
